from lib import *
S = SS('p60')
steps = [
    step("页面有一个 img、一个 script,script 里 fetch 一个 gzip 压缩的 JSON。CDP 开着 Network:5 个请求(含浏览器自己请求的 /favicon.ico,返回 404)各有 requestWillBeSent、responseReceived、loadingFinished 事件,另有 dataReceived 9 个。每个请求都能用 requestId 调 Network.getResponseBody:文本类型直接给出文本,图片 /a.png(70 字节)给出 96 个字符的 base64,base64Encoded 为 True。", t=tl(S(1)), done=lidx(S(1), '事件个数'), b=bars([['请求数', 5, '5'], ['dataReceived 事件', 9, '9'], ['/a.png 原始字节', 70, '70'], ['/a.png base64 长度', 96, '96']], 100, done=[0, 1], mark=[3]), kv=KV([['事件', 'requestWillBeSent → responseReceived → loadingFinished'], ['文本', 'base64Encoded=False'], ['图片', 'base64Encoded=True']], ['图片'])),
    step("/api/data 服务器发出的 gzip 正文是 16477 字节(响应头 Content-Length 也是 16477),loadingFinished 里的 encodedDataLength 是 16627,getResponseBody 给出的是已经解压的文本:258780 字符,解析成 3000 个对象。encodedDataLength 比 gzip 正文多 150 字节,多出的应该是响应头(这是我的推断,没有逐字节核对)。也就是说,通过 CDP 拿到的响应体是浏览器解压之后的内容,不用自己处理 Content-Encoding;但网络上传输的字节数要看 encodedDataLength。", t=tl(S(2)), done=lidx(S(2), '网络上传输的字节数'), b=bars([['gzip 正文', 16477, '16477'], ['encodedDataLength', 16627, '16627'], ['getResponseBody 文本', 258780, '258780']], 270000, done=[2], mark=[0, 1]), kv=KV([['网络上的字节', '16627'], ['getResponseBody', '解压后 258780 字符'], ['解析', '3000 个对象']], ['getResponseBody'])),
    step("什么时候可以取:/slow 先发响应头,正文 2000 字节分两块、中间停 0.6 秒。responseReceived 到达时(正文还没发完)调 getResponseBody,返回错误 “No data found for resource with give…”(输出被截断,后面是 identifier);等到 loadingFinished 之后再取(距 responseReceived 1.26 秒),取到 2000 字节,和页面 JS 里收到的长度一致。要在 loadingFinished 事件之后再取。", t=tl(S(3)), done=lidx(S(3), 'loadingFinished 到达后取'), mark=lidx(S(3), 'responseReceived 到达时'), b=bars([['responseReceived 时取到的字节', 0, '0(报错)'], ['loadingFinished 后取到的字节', 2000, '2000']], 2200, mark=[0], done=[1]), kv=KV([['responseReceived 时', '报错:没有数据'], ['loadingFinished 之后', '取到 2000 字节'], ['等待', '1.26 秒']], ['loadingFinished 之后'])),
    step("重定向和页面跳走:访问 /redir(302 到 /api/data),requestWillBeSent 里带 redirectResponse 的有 1 个,状态 302,Location=/api/data——重定向这一跳的信息在下一个请求的事件里。页面跳走以后:再用之前那个页面里 /api/data 的 requestId 取 getResponseBody,返回错误 “No resource with given identifier fo…”(输出被截断)。响应体要在页面还在的时候取走。", t=tl(S(4)), done=lidx(S(4), '跳转之后'), mark=lidx(S(4), '访问 /redir'), b=bars([['redirectResponse 事件', 1, '1'], ['跳走后能取到的响应体', 0, '0']], 2, done=[0], mark=[1]), kv=KV([['302 的信息', '在下一个请求的 redirectResponse 里'], ['页面跳走后', '旧 requestId 取不到'], ['做法', '在页面还在时取走']], ['做法'])),
    step("Network.setBlockedURLs 阻止 *.png:服务器收到 /a.png 0 次(不阻止时 1 次),其它 3 个请求照常,页面 JS 里 window.n 仍是 3000,浏览器侧 loadingFailed 1 个(blockedReason 为 inspector)。被阻止的请求浏览器根本没有发出去,不占流量,也不影响页面的其它部分。", t=tl(S(5)), done=lidx(S(5), '阻止 *.png'), mark=lidx(S(5), '不阻止'), b=bars([['不阻止:/a.png 请求', 1, '1'], ['阻止 *.png:/a.png 请求', 0, '0'], ['两种情形下的 window.n', 3000, '3000']], 3000, mark=[0], done=[1, 2]), kv=KV([['不阻止', '服务器收到 /a.png 1 次'], ['阻止 *.png', '0 次,loadingFailed 1 个'], ['页面', 'window.n 仍是 3000']], ['阻止 *.png'])),
    step("事后取响应体有上限:连续 150 个 1 MiB 不可压缩的响应,默认设置下事后取得到 142 个(第 8–149 个,最早的 8 个被丢掉);maxTotalBufferSize 设成 10 MiB 只取得到 7 个(第 143–149 个);设成 1 GiB 全部 150 个都取得到。默认设置下旧的响应体会被挤掉,大量大响应要在 loadingFinished 时就取走。", t=tl(S(6)), done=lidx(S(6), 'maxTotalBufferSize=1 GiB'), mark=lidx(S(6), 'maxTotalBufferSize=10 MiB'), b=bars([['默认:事后取得到', 142, '142'], ['10 MiB:事后取得到', 7, '7'], ['1 GiB:事后取得到', 150, '150']], 150, mark=[1], done=[2]), kv=KV([['默认', '142 / 150,最早 8 个被挤掉'], ['maxTotalBufferSize=10 MiB', '7 / 150'], ['maxTotalBufferSize=1 GiB', '150 / 150']], ['默认'])),
]
A = mkartp('p60', 60, '爬虫,CDP,Network,getResponseBody,Chrome,headless,屏蔽资源,Python,真实验证,动画演示',
    '在本机页面上实测 CDP Network 域:事件顺序、getResponseBody 返回的是解压后的文本(图片是 base64)、必须等到 loadingFinished 才能取、页面跳走后取不到、setBlockedURLs 能挡住图片请求、默认缓冲下 150 个 1 MiB 响应事后只取得到 142 个。',
    '页面里的数据多半是 JS 发请求拿来的。用浏览器抓取时,与其解析渲染后的 HTML,不如直接让 CDP 把网络响应体交出来。这篇用一个本机页面测 Network 事件的顺序、什么时候能取响应体,以及取不到的几种情况。',
    [('258780 对 16627', '/api/data 经 getResponseBody 拿到的字符数(已解压) 与 loadingFinished 里记的网络字节数(encodedDataLength)'), ('0 对 2000 字节', '在 responseReceived 时取到的字节(报错) 与 在 loadingFinished 之后取到的字节'), ('142 / 150', '连续收到 150 个 1 MiB 的响应后,默认缓冲下事后还取得到的个数(设成 1 GiB 全部取得到)')],
    [('一个请求的事件', '<p>开着 Network 域,每个请求会按 requestWillBeSent、responseReceived、(若干 dataReceived)、loadingFinished 的顺序给出事件,用 requestId 关联。type 字段区分 Document、Script、Image、Fetch 等。实验里页面只有 img 和 script,浏览器还自己请求了 /favicon.ico,一共 5 个请求。getResponseBody 对文本给出文本,对图片给出 base64。</p>'),
     ('解压之后的响应体', '<p>响应带了 Content-Encoding: gzip 时,getResponseBody 给出的是浏览器已经解压的内容,不用自己解压。loadingFinished 里的 encodedDataLength 是网络上传输的字节数。实验里 gzip 正文 16477 字节,encodedDataLength 是 16627,解压后的文本 258780 字符(多出的 150 字节我推测是响应头,没有逐字节核对)。</p>'),
     ('什么时候能取', '<p>响应头到了(responseReceived)不等于正文到了。正文还在传输时调 getResponseBody 会报错 “No data found for resource with give…”(输出被截断,后面是 identifier);等 loadingFinished 之后才取得到。实验里 /slow 的正文分两块,中间停 0.6 秒。</p>'),
     ('重定向与页面跳走', '<p>重定向的那一跳在下一个 requestWillBeSent 的 redirectResponse 字段里(状态、Location)。页面跳走之后,旧页面的 requestId 取 getResponseBody 会报 “No resource with given identifier fo…”(输出被截断)。所以要在页面还在的时候取走需要的响应体。</p>'),
     ('少下载', '<p>Network.setBlockedURLs 能让浏览器不发出匹配的请求(实验里图片请求没有到达服务器,页面其余部分照常工作),对不需要图片、样式的抓取能省流量。</p>'),
     ('别被挤掉', '<p>DevTools 会缓存响应体供事后查看,缓冲有上限:实验里默认设置下连续 150 个 1 MiB 的响应,事后只取得到 142 个,最早的 8 个被挤掉;把 maxTotalBufferSize 设成 10 MiB 就只剩最后 7 个。大量或大的响应要在 loadingFinished 时就取走,不要攒到最后。</p>')],
    steps,
    [ENV_P + '。页面和接口都在本机服务器上(img、script、一个 258780 字节压缩成 16477 字节的 JSON、一个分块慢响应 /slow、一个 302、可指定大小的不可压缩响应 /blob);Chrome 154 通过 pcdp.py 控制,用 Network.enable 读事件(要持续读 websocket 才收得到事件),各情形跑一次',
     '没有验证:默认缓冲上限的具体数值(只观察到 150 个 1 MiB 的响应里最早 8 个被挤掉,没有去确定它是按字节还是按个数、阈值是多少);Fetch 域(拦截并修改请求/响应);跨域 iframe、Service Worker、Web Worker 里的请求(需要 Target.setAutoAttach 才看得到,没有试);HTTP/2 和 HTTPS 下的差别;encodedDataLength 比 gzip 正文多出的 150 字节到底是什么'],
    'CDP 网络事件')
